<template><div class="page-container fsr-page"><div class="page-head"><div><h2>任务流程库</h2><p>按结构化节点记录任务下发、核查、上报、审核、整改和结案。</p></div><el-button type="primary" @click="load">刷新流程</el-button></div><div class="panel"><div class="panel-title">任务流程列表</div><el-tabs v-model="tab"><el-tab-pane v-for="i in flowTabs" :key="i.value" :label="`${i.label}（${groups[i.value].length}）`" :name="i.value"><el-table :data="groups[i.value]" stripe border><el-table-column prop="taskId" label="流程编号" width="150"><template #default="{row}">{{ row.taskId||'待生成' }}</template></el-table-column><el-table-column prop="code" label="图斑编号" width="145"/><el-table-column prop="regionName" label="所在位置" min-width="150"/><el-table-column label="下发时间" width="145"><template #default="{row}">{{ row.dispatchedAt||'待下发' }}</template></el-table-column><el-table-column label="核查责任人/单位" min-width="180"><template #default="{row}">{{ row.checkResponsiblePerson||row.checkResponsibleUnit||row.assignee||'待明确' }}</template></el-table-column><el-table-column label="核查时间" width="130"><template #default="{row}">{{ row.checkedAt||'待核查' }}</template></el-table-column><el-table-column label="上报时间" width="130"><template #default="{row}">{{ row.reportedAt||'待上报' }}</template></el-table-column><el-table-column label="审核人" width="125"><template #default="{row}">{{ row.auditor||'待审核' }}</template></el-table-column><el-table-column label="审核时间" width="130"><template #default="{row}">{{ row.auditedAt||'待审核' }}</template></el-table-column><el-table-column label="处置措施" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.completionDescription||row.rectifyNote?.desc||row.auditOpinion||'待明确' }}</template></el-table-column><el-table-column label="当前状态" width="105"><template #default="{row}"><el-tag>{{ statusName(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="primary" @click="openDispatch(row)">派发</el-button><el-button v-else link type="primary" @click="showTrail(row)">流程</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></div><el-dialog v-model="visible" title="派发核查任务" width="520px"><el-form label-width="90px"><el-form-item label="图斑编号">{{ current?.code }}</el-form-item><el-form-item label="核查责任人"><el-input v-model="form.assignee"/></el-form-item><el-form-item label="核查截止"><el-input-number v-model="form.deadlineDays" :min="1" :max="60"/></el-form-item><el-form-item label="计划落实"><el-input v-model="form.requirement" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">确认派发</el-button></template></el-dialog><el-dialog v-model="trailVisible" title="任务流程"><el-timeline><el-timeline-item v-for="(i,n) in current?.trail||[]" :key="n" :timestamp="i.time">{{ i.action }}<span class="trail-user">{{ i.user }}</span><div>{{ i.extra||i.opinion }}</div></el-timeline-item></el-timeline></el-dialog></div></template>
<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { fetchEvents,dispatchTask } from '@/api/fsr';import { useUserStore } from '@/stores/user';const userStore=useUserStore();const rows=ref([]);const tab=ref('pending');const visible=ref(false);const trailVisible=ref(false);const current=ref(null);const form=reactive({assignee:'',deadlineDays:7,requirement:''});const flowTabs=[{label:'已下发',value:'pending'},{label:'待核查',value:'checking'},{label:'已上报',value:'reported'},{label:'待审核',value:'reviewing'},{label:'已审核',value:'rectifying'},{label:'需复查',value:'recheck'},{label:'已结案',value:'closed'}];const groups=reactive(Object.fromEntries(flowTabs.map(i=>[i.value,[]])));const map={pending:'已下发',checking:'待核查',reviewing:'待审核',reported:'已上报',rectifying:'已审核',recheck:'需复查',closed:'已结案'};const statusName=x=>map[x]||'未知状态';const flowStatus=e=>e.status==='reviewing'&&e.reportedAt?'reviewing':e.status;const load=async()=>{rows.value=await fetchEvents(userStore.role,{});flowTabs.forEach(i=>groups[i.value]=rows.value.filter(e=>flowStatus(e)===i.value))};const openDispatch=r=>{current.value=r;form.assignee=r.assignee||'';form.requirement='';visible.value=true};const submit=async()=>{if(!form.assignee.trim())return ElMessage.warning('请填写核查责任人');const r=await dispatchTask(current.value.id,form);if(!r.success)return ElMessage.error(r.message||'派发失败');ElMessage.success('任务已派发');visible.value=false;load()};const showTrail=r=>{current.value=r;trailVisible.value=true};onMounted(load)
</script><style scoped lang="scss">.fsr-page{overflow:auto}.page-head{display:flex;justify-content:space-between;margin-bottom:14px}.page-head h2{margin:4px 0;font-size:22px}.page-head p{margin:0;color:var(--ah-text-secondary);font-size:13px}.panel-title{margin-bottom:12px;font-weight:700}.trail-user{margin-left:12px;color:#8492a6}</style>